// The method copy inside each eval case.
//
// `claude plugin eval` runs load no CLAUDE.md, so a case cannot see the method
// that `lets-set-up` installs. Each case therefore carries its own copy, as
// `append_system_prompt`, between two marker comments in its case.yaml:
//
//   execution:
//     # BEGIN method — generated by `npm run evals:sync`; do not edit
//     # END method
//
// A case can also carry a user's profile: evals/<case>/profile.md is added after
// the method block, the way `lets-set-up` writes a profile below the method in CLAUDE.md.
//
// `sync-eval-method.mjs` writes the copy; `validate.mjs` fails when a copy is
// older than skills/lets-set-up/method.md or the case's profile.md.

import { readdirSync, existsSync, readFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
export const EVALS = join(ROOT, "evals");
export const METHOD = join(ROOT, "skills", "lets-set-up", "method.md");

const BEGIN = "# BEGIN method — generated by `npm run evals:sync`; do not edit";
const END = "# END method";

// The same wrapper the `lets-set-up` skill writes into a user's CLAUDE.md.
function wrapped(methodText) {
  return [
    "<!-- dont-run-off:method — managed, replaced on upgrade. Edit below this block. -->",
    ...methodText.trimEnd().split("\n"),
    "<!-- /dont-run-off:method -->",
  ];
}

// The YAML lines between (and including) the two markers, at `indent`.
function block(methodText, indent, profileText) {
  const profile = profileText ? ["", ...profileText.trimEnd().split("\n")] : [];
  return [
    `${indent}${BEGIN}`,
    `${indent}append_system_prompt: |`,
    ...[...wrapped(methodText), ...profile].map((l) => (l ? `${indent}  ${l}` : "")),
    `${indent}${END}`,
  ];
}

// Returns { found: false } when the case has no method markers,
// { found: true, error } when the markers are broken, and
// { found: true, text } with the case.yaml text that holds the current copy.
export function withMethod(yamlText, methodText, profileText = null) {
  const lines = yamlText.split("\n");
  const begin = lines.findIndex((l) => l.trim().startsWith("# BEGIN method"));
  if (begin === -1) return { found: false };
  const end = lines.findIndex((l, i) => i > begin && l.trim() === END);
  if (end === -1)
    return { found: true, error: `'# BEGIN method' has no '${END}' after it` };
  const indent = lines[begin].match(/^\s*/)[0];
  const next = [
    ...lines.slice(0, begin),
    ...block(methodText, indent, profileText),
    ...lines.slice(end + 1),
  ];
  return { found: true, text: next.join("\n") };
}

// Every evals/<case>/case.yaml, as { rel, path, profile }. `profile` is the
// text of the case's profile.md, or null.
export function caseFiles() {
  if (!existsSync(EVALS)) return [];
  return readdirSync(EVALS, { withFileTypes: true })
    .filter((d) => d.isDirectory() && d.name !== "results")
    .map((d) => {
      const profilePath = join(EVALS, d.name, "profile.md");
      return {
        rel: `evals/${d.name}/case.yaml`,
        path: join(EVALS, d.name, "case.yaml"),
        profile: existsSync(profilePath) ? readFileSync(profilePath, "utf8") : null,
      };
    })
    .filter((c) => existsSync(c.path));
}
